fn cleanup_stale_protected_stages(vault:&Mutex<Vault>,active:&std::sync::atomic::AtomicBool)->Result<(),String>{let names={let v=vault.lock().map_err(|_|"workspace unavailable")?;v.stale_purge_index_tables()?};for name in names{loop{if !active.load(std::sync::atomic::Ordering::Acquire){return Err("workspace unavailable".into())}let done={let v=vault.lock().map_err(|_|"workspace unavailable")?;v.cleanup_purge_index_table_step(&name)?};if done{break}std::thread::yield_now();}}Ok(())}
