 #[test] fn external_unlock_replays_search_edits(){
  let dir=std::env::temp_dir().join(format!("atlas-external-derived-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&dir).unwrap();let path=dir.join("workspace.atlas");let mut v=Vault::create(&path,"secret").unwrap();v.set_workspace_name("test").unwrap();v.put_note("n","title","before").unwrap();v.enable_search_journal().unwrap();let mut stage=atlas_sqlcipher_proof::search_stage::build_search_stage(&v,&dir,"secret").unwrap();while !v.pending_search_updates(1).unwrap().is_empty(){stage.replay_pending(&v,"secret",256).unwrap();}v.experimental_search_cutover(&stage,&dir.join(atlas_sqlcipher_proof::search_index_name(stage.generation()).unwrap()),&dir.join("backup"),"secret",||Ok(())).unwrap();drop(v);drop(stage);std::fs::write(dir.join(".atlas-protected"),b"atlas-protected-v1").unwrap();std::fs::write(dir.join(".workspace.json"),r#"{"name":"test","protected":true}"#).unwrap();let guard=Arc::new(crate::protected_external_guard::ProtectedExternalGuard::acquire(std::fs::File::open(&dir).unwrap(),&dir).unwrap());let mut worker=ProtectedWorker::new(&dir,guard);worker.dispatch(&json!({"action":"unlock","password":"secret"})).unwrap();worker.dispatch(&json!({"action":"put-note","id":"n","title":"title","text":"after"})).unwrap();let until=std::time::Instant::now()+std::time::Duration::from_secs(5);loop{if worker.vault.as_ref().unwrap().lock().unwrap().search("after").is_ok_and(|x|x==vec!["n"]){break}assert!(std::time::Instant::now()<until);std::thread::sleep(std::time::Duration::from_millis(20));}worker.dispatch(&json!({"action":"close"})).unwrap();drop(worker);std::fs::remove_dir_all(dir).unwrap();
 }
